<?php
namespace App\Http\Controllers;
use App\Models\{User,Apprentice,EmployerApprenticeGrant,ReviewAppointment as Appointment};
use App\Support\{ReviewAppointments as A,ReviewMeetingFollowup as F,StaffDuties,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\Support\Str;
class ReviewAppointmentsController extends Controller {
 private function view(string $v,array $d=[]) {return response()->view('review-appointments.'.$v,$d)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function auth(Request $r):int {return (int)$r->session()->get('auth_version');}
 private function staff(Request $r,Apprentice $a):void {abort_unless(A::staff($r->user(),$a),403);}
 private function access(Request $r,Appointment $appointment):void {abort_unless(A::visible($r->user(),$appointment),404);abort_unless(A::intact($appointment),409,'Appointment evidence needs checking.');}
 private function owners(Apprentice $a) {return User::where('active',true)->orderBy('name')->get()->filter(fn($u)=>A::staff($u,$a));}
 private function rows(Request $r):array {
  abort_unless(in_array($r->user()->role,['admin','ceo','tutor','apprentice','employer'],true)||StaffDuties::has($r->user(),'mentor'),403);
  $d=$r->validate(['from'=>['nullable','date_format:Y-m-d'],'to'=>['nullable','date_format:Y-m-d','after_or_equal:from'],'state'=>['nullable','in:Draft,Published,Cancelled,Reported'],'page'=>['nullable','integer','min:1']]);$from=$d['from']??today()->subDays(90)->toDateString();$to=$d['to']??today()->addDays(180)->toDateString();abort_if(\Carbon\Carbon::parse($from)->diffInDays($to,true)>366,422,'Use at most366 days.');
  $q=Appointment::whereDate('starts_at','>=',$from)->whereDate('starts_at','<=',$to)->when($d['state']??null,fn($q,$s)=>$q->where('state',$s));
  if(!LearningAccess::manager($r->user())) {$ids=Apprentice::get()->filter(fn($a)=>A::staff($r->user(),$a))->pluck('id');$q->where(fn($q)=>$q->whereIn('apprentice_id',$ids)->orWhereIn('id',\App\Models\ReviewAppointmentParty::where('user_id',$r->user()->id)->select('appointment_id')));}
  $raw=$q->orderBy('starts_at')->orderBy('id')->limit(1001)->get();abort_if($raw->count()>1000,422,'Narrow the date/state filters.');$rows=[];foreach($raw as$p){if(!A::visible($r->user(),$p)){continue;}$a=Apprentice::find($p->apprentice_id);$staff=A::staff($r->user(),$a);$rows[]=['p'=>$p,'staff'=>$staff,'intact'=>A::intact($p),'current'=>A::current($p),'availability'=>$staff?A::availability($p):null,'followup'=>$staff?F::position($p):null];}return compact('rows','d','from','to');
 }
 public function index(Request $r) {$data=$this->rows($r);$page=(int)$r->input('page',1);$data['items']=new LengthAwarePaginator(array_slice($data['rows'],($page-1)*25,25),count($data['rows']),25,$page,['path'=>$r->url(),'query'=>$r->except('page')]);return $this->view('index',$data);}
 public function export(Request $r) {abort_unless(in_array($r->user()->role,['admin','ceo','tutor'],true)||StaffDuties::has($r->user(),'mentor'),403);$data=$this->rows($r);$rows=[];foreach($data['rows']as$row){if(!$row['staff']){continue;}$p=$row['p'];$rows[]=['id'=>$p->id,'apprentice_id'=>$p->apprentice_id,'starts_at'=>$p->starts_at->toIso8601String(),'ends_at'=>$p->ends_at->toIso8601String(),'state'=>$p->state,'version'=>$p->version,'source_current'=>$row['current'],'availability'=>$row['availability'],'followup'=>$row['followup']];}return response()->json(['rows'=>$rows,'private_names_notes_and_locations_exported'=>false,'review_completion_inferred'=>false],200,['Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer','Content-Disposition'=>'attachment; filename="GTA-Review-Appointments.json"']);}
 public function form(Request $r,Apprentice $apprentice,?Appointment $appointment=null) {$this->staff($r,$apprentice);if($appointment){abort_unless($appointment->apprentice_id===$apprentice->id,404);abort_unless(A::intact($appointment),409);abort_unless(in_array($appointment->state,['Draft','Published'],true)&&$appointment->starts_at->gt(now()),409);}$grants=EmployerApprenticeGrant::where('apprentice_id',$apprentice->id)->get();$hosts=User::where('active',true)->orderBy('name')->get()->filter(fn($u)=>LearningAccess::tutor($u,$apprentice)||StaffDuties::assigned($u,$apprentice,'mentor'));$options=[];foreach($grants as$g){foreach($hosts as$h){try{A::basis($apprentice,$g->id,$h->id);$options[$g->id]=User::find($g->user_id)->name;}catch(\Throwable){}}}return $this->view('form',['a'=>$apprentice,'p'=>$appointment,'options'=>$options,'hosts'=>$hosts,'token'=>(string)Str::uuid()]);}
 public function save(Request $r,Apprentice $apprentice,?Appointment $appointment=null) {$this->staff($r,$apprentice);$d=$r->validate(['request_token'=>['required','uuid'],'version'=>['required','integer','min:0'],'grant_id'=>['required','integer','min:1'],'host_id'=>['required','integer','min:1'],'date'=>['required','date_format:Y-m-d'],'start'=>['required','date_format:H:i'],'end'=>['required','date_format:H:i'],'mode'=>['required','in:'.implode(',',A::MODES)],'place'=>['required','string','max:500'],'confirmed'=>['accepted']]);$p=A::save($r->user(),$this->auth($r),$apprentice,$appointment,(int)$d['version'],$d['request_token'],$d);return to_route('review-appointments.show',$p)->with('status','Draft saved. Publish after checking the named participants; rescheduling requires fresh availability.');}
 public function show(Request $r,Appointment $appointment) {$this->access($r,$appointment);$a=Apprentice::findOrFail($appointment->apprentice_id);$staff=A::staff($r->user(),$a);$p=$appointment;$current=A::current($p);return $this->view('show',['p'=>$p,'a'=>$a,'staff'=>$staff,'current'=>$current,'source'=>$p->source,'own'=>A::response($p,$r->user()),'party'=>isset($p->source['basis']['parties'])&&collect($p->source['basis']['parties'])->contains('id',$r->user()->id),'availability'=>$staff?A::availability($p):null,'preparation'=>$staff?A::preparation($p):null,'position'=>$staff?F::position($p):null,'owners'=>$staff?$this->owners($a):collect(),'replacements'=>$staff?Appointment::where('apprentice_id',$a->id)->where('id','!=',$p->id)->where('state','Published')->where('starts_at','>',now())->get()->filter(fn($n)=>A::published($n)&&A::current($n)):collect()]);}
 private function change(Request $r):array {return $r->validate(['version'=>['required','integer','min:1'],'confirmed'=>['accepted']]);}
 public function publish(Request $r,Appointment $appointment) {$this->staff($r,Apprentice::findOrFail($appointment->apprentice_id));$d=$this->change($r);A::publish($r->user(),$this->auth($r),$appointment,(int)$d['version']);return back()->with('status','Published in the portal for the three named accounts. No external invitation sent.');}
 public function cancel(Request $r,Appointment $appointment) {$this->staff($r,Apprentice::findOrFail($appointment->apprentice_id));$d=$this->change($r);$n=$r->validate(['note'=>['required','string','max:2000']]);A::cancel($r->user(),$this->auth($r),$appointment,(int)$d['version'],$n['note']);return back()->with('status','Appointment cancelled. Check any downloaded calendar copies separately.');}
 public function respond(Request $r,Appointment $appointment) {$this->access($r,$appointment);$d=$this->change($r);$v=$r->validate(['response_version'=>['required','integer','min:0'],'choice'=>['required','in:'.implode(',',A::CHOICES)]]);A::respond($r->user(),$this->auth($r),$appointment,(int)$d['version'],(int)$v['response_version'],$v['choice']);return back()->with('status','Your availability saved for this appointment version.');}
 public function calendar(Request $r,Appointment $appointment) {$this->access($r,$appointment);return response(A::calendar($appointment),200,['Content-Type'=>'text/calendar; charset=UTF-8','Content-Disposition'=>'attachment; filename="GTA-review-'.$appointment->id.'.ics"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function outcome(Request $r,Appointment $appointment) {$this->staff($r,Apprentice::findOrFail($appointment->apprentice_id));$d=$this->change($r);$v=$r->validate(['kind'=>['required','in:Held,Partial,Not held'],'participation'=>['required','array:apprentice,employer,host'],'participation.*'=>['required','in:'.implode(',',F::PARTICIPATION)],'note'=>['required','string','max:2000'],'owner_id'=>['nullable','integer','min:1'],'due_on'=>['nullable','date_format:Y-m-d','after_or_equal:today'],'action'=>['nullable','string','max:2000']]);$parties=[];foreach(A::ROLES as$k=>$label){$parties[$k]=$v['participation'][$k]??'';}$v['participation']=$parties;F::record($r->user(),$this->auth($r),$appointment,(int)$d['version'],$v);return back()->with('status','Staff-reported operational outcome saved. Complete the formal review through its existing preparation and sign-off process.');}
 public function link(Request $r,Appointment $appointment) {$this->staff($r,Apprentice::findOrFail($appointment->apprentice_id));$d=$this->change($r);$v=$r->validate(['followup_version'=>['required','integer','min:0'],'replacement_id'=>['required','uuid'],'replacement_version'=>['required','integer','min:1'],'note'=>['required','string','max:2000']]);F::link($r->user(),$this->auth($r),$appointment,(int)$d['version'],(int)$v['followup_version'],Appointment::findOrFail($v['replacement_id']),(int)$v['replacement_version'],$v['note']);return back()->with('status','Current replacement linked. New participants must answer separately; review completion remains separate.');}
}
